export class LinkedList {
  constructor() {
    this.head = null;
    this.size = 0;
  }
  push(val) {
    const node = { value: val, next: null };
    if (!this.head) { this.head = node; }
    else {
      let cur = this.head;
      while (cur.next) cur = cur.next;
      cur.next = node;
    }
    this.size++;
  }
  pop() {
    if (!this.head) return undefined;
    if (!this.head.next) {
      const val = this.head.value;
      this.head = null;
      this.size--;
      return val;
    }
    let cur = this.head;
    while (cur.next.next) cur = cur.next;
    const val = cur.next.value;
    cur.next = null;
    this.size--;
    return val;
  }
  find(val) {
    let cur = this.head;
    while (cur) {
      if (cur.value === val) return cur;
      cur = cur.next;
    }
    return null;
  }
}
